import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
export async function exerciseCollageProject(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,dialog=()=>page.getByRole('dialog',{name:t('照片拼图','Photo collage'),exact:true}),button=(zh,en)=>dialog().getByRole('button',{name:t(zh,en),exact:true}),tool=()=>page.locator('.studio-tool').filter({hasText:t('照片拼图','Photo collage')});
 const raw=await page.evaluate(async()=>{const c=new OffscreenCanvas(100,60),x=c.getContext('2d');x.fillStyle='#bb7744';x.fillRect(0,0,100,60);return [...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())];});const file={name:'Stored-collage.png',mimeType:'image/png',buffer:Buffer.from(raw)};
 await dialog().locator('input[type=file]').first().setInputFiles(file);await expect(button('保存到图库','Save to library')).toBeEnabled();await dialog().getByLabel(t('工程名称','Project name'),{exact:true}).fill('Saved collage');await dialog().getByLabel(t('格内缩放','Cell zoom'),{exact:true}).fill('1.7');await button('保存到图库','Save to library').click();await expect(button('另存拼图工程','Save project copy')).toBeEnabled();await expect(dialog().locator('.collage-projects')).toContainText(t('版本 1','Revision 1'));
 await button('关闭','Close').click();await expect(dialog()).toHaveCount(0);await tool().click();await button('图库内拼图工程','Library collage projects').click();await expect(dialog().locator('.collage-project-list li')).toHaveCount(1);await dialog().locator('.collage-project-list').getByRole('button',{name:t('打开工程','Open project'),exact:true}).click();await expect(dialog().getByLabel(t('格内缩放','Cell zoom'),{exact:true})).toHaveValue('1.7');
 await dialog().getByLabel(t('画布宽度','Canvas width'),{exact:true}).fill('640');await dialog().getByLabel(t('画布宽度','Canvas width'),{exact:true}).press('Tab');
 await button('图库内拼图工程','Library collage projects').click();const native=new URL(page.url()).port==='4174';if(native)await page.route('**/api/editor/collages/*',route=>route.fulfill({status:409,contentType:'application/json',body:JSON.stringify({detail:'Collage project sources are missing or changed. Restore a backup.'})}));else await page.evaluate(()=>{const proto=FileSystemFileHandle.prototype,get=proto.getFile;window.__restoreCollageRead=()=>{proto.getFile=get;};proto.getFile=async function(){if(this.name.endsWith('.bin'))throw new DOMException('Synthetic snapshot failure','NotReadableError');return get.call(this);};});page.once('dialog',d=>d.accept());await dialog().locator('.collage-project-list').getByRole('button',{name:t('打开工程','Open project'),exact:true}).click();const errorModal=page.getByRole('dialog',{name:t('打开拼图工程','Open collage project'),exact:true});await expect(errorModal.getByRole('alert')).toBeVisible();await expect(dialog()).toHaveCount(0);await errorModal.getByRole('button',{name:t('关闭','Close'),exact:true}).click();if(native)await page.unroute('**/api/editor/collages/*');else await page.evaluate(()=>window.__restoreCollageRead());await expect(dialog().getByLabel(t('画布宽度','Canvas width'),{exact:true})).toHaveValue('640');await expect(dialog().getByLabel(t('格内缩放','Cell zoom'),{exact:true})).toHaveValue('1.7');await button('图库内拼图工程','Library collage projects').click();
await button('保存到图库','Save to library').click();await expect(dialog().locator('.collage-projects')).toContainText(t('版本 2','Revision 2'));
 const next=page.waitForEvent('download');await button('保存布局清单','Save layout document').click();const manifest=JSON.parse(readFileSync(await(await next).path(),'utf8'));expect(manifest.cells[0].zoom).toBe(1.7);expect(manifest.width).toBe(640);
 await button('另存拼图工程','Save project copy').click();await expect(dialog().locator('.collage-projects')).toContainText(t('版本 1','Revision 1'));await button('图库内拼图工程','Library collage projects').click();await expect(dialog().locator('.collage-project-list li')).toHaveCount(2);
 await dialog().evaluate(e=>e.scrollTop=0);await dialog().screenshot({path:info.outputPath('collage-project-'+lang+'.png')});expect(await dialog().evaluate(e=>e.scrollWidth<=e.clientWidth+1)).toBe(true);if(lang==='en')expect(await dialog().innerText()).not.toMatch(/[\u3400-\u9fff]/);
 page.once('dialog',d=>d.accept());await dialog().locator('.collage-project-list li').last().getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();await expect(dialog().locator('.collage-project-list li')).toHaveCount(1);page.once('dialog',d=>d.accept());await dialog().locator('.collage-project-list li').getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();await expect(dialog().locator('.collage-project-list li')).toHaveCount(0);await expect(button('另存拼图工程','Save project copy')).toHaveCount(0);await button('保存到图库','Save to library').click();await expect(button('另存拼图工程','Save project copy')).toBeEnabled();page.once('dialog',d=>d.accept());await dialog().locator('.collage-project-list li').getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();await expect(dialog().locator('.collage-project-list li')).toHaveCount(0);page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog()).toHaveCount(0);
 await tool().click();await button('批量拼图','Batch collage').click();const batch=()=>page.getByRole('dialog',{name:t('批量拼图','Batch collage'),exact:true}),b=(zh,en)=>batch().getByRole('button',{name:t(zh,en),exact:true});await batch().locator('input[type=file]').first().setInputFiles([file,{...file,name:'Second.png'},{...file,name:'Third.png'}]);await expect(b('保存到图库','Save to library')).toBeEnabled();await batch().getByLabel(t('工程名称','Project name'),{exact:true}).fill('Saved batch');await b('保存到图库','Save to library').click();await expect(b('另存拼图工程','Save project copy')).toBeEnabled();const download=page.waitForEvent('download');await b('保存批量清单','Save batch document').click();const savedBook=JSON.parse(readFileSync(await(await download).path(),'utf8'));await b('关闭','Close').click();await expect(batch()).toHaveCount(0);await tool().click();await button('图库内拼图工程','Library collage projects').click();await dialog().locator('.collage-project-list').getByRole('button',{name:t('打开工程','Open project'),exact:true}).click();await expect(b('保存批量清单','Save batch document')).toBeEnabled();const reopened=page.waitForEvent('download');await b('保存批量清单','Save batch document').click();expect(JSON.parse(readFileSync(await(await reopened).path(),'utf8'))).toEqual(savedBook);await b('图库内拼图工程','Library collage projects').click();page.once('dialog',d=>d.accept());await batch().locator('.collage-project-list').getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();await expect(batch().locator('.collage-project-list li')).toHaveCount(0);page.once('dialog',d=>d.accept());await b('关闭','Close').click();await expect(batch()).toHaveCount(0);

}
